void require(bool ok,const char* why){if(!ok)throw std::runtime_error(std::string("STEP review: ")+why);}
QByteArray bytes(const QString& path,qint64 cap=16*1024*1024){QFile file(path);require(file.open(QIODevice::ReadOnly)&&file.size()>0&&file.size()<=cap,"file missing or outside byte budget");auto data=file.read(cap+1);require(file.error()==QFileDevice::NoError&&data.size()<=cap,"file read failed");return data;}
Json parse(const QByteArray& data){std::vector<std::set<std::string>> keys;return Json::parse(data.toStdString(),[&](int depth,Json::parse_event_t event,Json& v){require(depth<=32,"JSON depth budget");if(event==Json::parse_event_t::object_start)keys.emplace_back();else if(event==Json::parse_event_t::key)require(keys.back().insert(v.get<std::string>()).second,"duplicate JSON key");else if(event==Json::parse_event_t::object_end)keys.pop_back();return true;});}
void fields(const Json& j,std::set<std::string> names){require(j.is_object()&&j.size()==names.size(),"missing/extra fields");for(auto it=j.begin();it!=j.end();++it)require(names.count(it.key())!=0,"unsupported field");}
void equal(const Json& a,const Json& b,const char* why){require(a==b,why);}
Json verifyVolumeAudit(const Json& audit,const Json& source,const Json& inventory,const Json& solid){
    require(audit.at("schema")=="scdat.step-volume-audit/1"&&audit.at("policy")=="scdat.adaptive-volume-reference/1"&&audit.at("target_unit")=="mm"&&audit.at("transport_allowed")==false&&audit.at("source_fidelity_certified")==false,"unsupported volume audit profile/claims");equal(audit.at("source"),source,"volume audit source mismatch");equal(audit.at("inventory"),inventory,"volume audit inventory mismatch");equal(audit.at("part_key"),solid.at("key"),"volume audit solid mismatch");
    const auto& topology=audit.at("topology");require(topology.at("valid")==true&&topology.at("solid_count")==1&&topology.at("shell_count").is_number_integer()&&topology.at("shell_count").get<int>()>0&&topology.at("all_shells_closed")==true,"volume audit topology not qualified");
    const auto& results=audit.at("results");require(results.is_array()&&results.size()==6,"six volume integrals required");double final[2]{},refinement=0;const double eps[3]={1e-9,1e-11,1e-13};
    for(int method=0;method<2;++method){double previous=0;for(int level=0;level<3;++level){const auto& row=results[method*3+level];require(row.at("method")== (method==0?"gauss":"kronrod")&&row.at("requested_eps")==eps[level],"unsupported integral sequence");double volume=row.at("volume_mm3").get<double>(),error=row.at("estimated_relative_error").get<double>();require(std::isfinite(volume)&&volume>0&&std::isfinite(error)&&error>=0,"invalid volume/error estimate");if(level>=1)require(error<=1e-9,"volume integral error estimate exceeds policy");if(level==2){final[method]=volume;refinement=std::max(refinement,std::abs(previous/volume-1));}previous=volume;}}
    double cross=std::abs(final[0]/final[1]-1),old=audit.at("default_volume_mm3").get<double>(),occ=solid.at("occ_volume_mm3").get<double>();require(std::isfinite(old)&&old>0&&std::abs(old/occ-1)<=1e-12&&cross<=1e-9&&refinement<=1e-9,"volume reference not converged/bound to default");
    const auto& assessed=audit.at("assessment");require(assessed.at("qualified")==true&&assessed.at("reference_method")=="adaptive_gauss_kronrod_use_span"&&assessed.at("assessment_relative_tolerance")==1e-9&&assessed.at("default_matches_inventory")==true,"volume assessment profile mismatch");equal(assessed.at("reference_volume_mm3"),final[1],"forged reference volume");require(std::abs(assessed.at("cross_method_relative").get<double>()-cross)<=1e-15&&std::abs(assessed.at("max_refinement_relative").get<double>()-refinement)<=1e-15,"forged volume convergence metrics");return assessed;
}


using AssemblyMatrix=std::array<std::array<double,4>,4>;
AssemblyMatrix assemblyMatrix(const Json& j){
    require(j.is_array()&&j.size()==4,"assembly matrix shape");AssemblyMatrix m{};
    for(int r=0;r<4;++r){require(j[r].is_array()&&j[r].size()==4,"assembly matrix row");for(int c=0;c<4;++c){require(j[r][c].is_number(),"assembly matrix scalar");m[r][c]=j[r][c].get<double>();require(std::isfinite(m[r][c])&&std::abs(m[r][c])<=1e9,"assembly matrix domain");}}
    require(m[3]==std::array<double,4>{0,0,0,1},"assembly homogeneous row");
    for(int r=0;r<3;++r)for(int c=0;c<3;++c){double dot=0;for(int k=0;k<3;++k)dot+=m[k][r]*m[k][c];require(std::abs(dot-(r==c?1.:0.))<=1e-10,"assembly rigid rotation required");}
    double det=m[0][0]*(m[1][1]*m[2][2]-m[1][2]*m[2][1])-m[0][1]*(m[1][0]*m[2][2]-m[1][2]*m[2][0])+m[0][2]*(m[1][0]*m[2][1]-m[1][1]*m[2][0]);require(std::abs(det-1)<=1e-10,"assembly reflection/scale unsupported");return m;
}
AssemblyMatrix assemblyProduct(const AssemblyMatrix& a,const AssemblyMatrix& b){AssemblyMatrix out{};for(int r=0;r<4;++r)for(int c=0;c<4;++c)for(int k=0;k<4;++k)out[r][c]+=a[r][k]*b[k][c];return out;}
void assemblyMatrixEqual(const AssemblyMatrix& a,const AssemblyMatrix& b){for(int r=0;r<4;++r)for(int c=0;c<4;++c)require(std::abs(a[r][c]-b[r][c])<=(c==3?1e-6:1e-10),"assembly parent/local/world composition mismatch");}
Vector3 assemblyPoint(const Json& j){require(j.is_array()&&j.size()==3,"assembly point shape");Vector3 p{};for(int k=0;k<3;++k){require(j[k].is_number(),"assembly point scalar");p[k]=j[k].get<double>();require(std::isfinite(p[k])&&std::abs(p[k])<=1e9,"assembly point domain");}return p;}
std::vector<std::size_t> assemblySamples(std::size_t n){std::vector<std::size_t> ids;auto count=std::min<std::size_t>(n,32);for(std::size_t i=0;i<count;++i)ids.push_back(count==1?0:i*(n-1)/(count-1));return ids;}
Json verifyAssemblyAudit(const Json& a,const Json& source,const Json& inventory,const Json& parts,const std::vector<MeshAssemblyPart>& meshes){
    require(a.at("schema")=="scdat.step-assembly-audit/1"&&a.at("policy")=="scdat.xde-sampled-correspondence/1"&&a.at("target_unit")=="mm"&&a.at("tolerance_mm")==1e-5&&a.at("sample_count")==32,"unsupported assembly policy");
    require(a.at("transport_allowed")==false&&a.at("source_fidelity_certified")==false&&a.at("provenance_authenticated")==false,"unsupported assembly certification claim");equal(a.at("source"),source,"assembly source mismatch");equal(a.at("inventory"),inventory,"assembly inventory mismatch");require(meshes.size()==parts.size(),"assembly requires mapped meshes");
    const auto& tree=a.at("tree");const auto& definitions=tree.at("definitions");const auto& nodes=tree.at("nodes");require(definitions.is_array()&&!definitions.empty()&&definitions.size()<=512&&nodes.is_array()&&!nodes.empty()&&nodes.size()<=512,"assembly tree budget");
    std::map<std::string,const Json*> defs,seen,leaves;std::map<std::string,int> depths,children;std::set<int> solidIndices;std::map<std::string,AssemblyMatrix> definitionMatrices;int roots=0;std::size_t totalPoints=0;for(const auto& m:meshes)totalPoints+=m.mesh.points.size();require(totalPoints<=200000,"assembly total mesh point budget");
    for(const auto& d:definitions){auto id=d.at("id").get<std::string>();require(!id.empty()&&id.size()<=256&&defs.emplace(id,&d).second&&d.at("is_assembly").is_boolean()&&d.at("name").is_string(),"duplicate/invalid definition");const auto& ps=d.at("feature_points_mm");require(ps.is_array()&&ps.size()<=32,"feature budget");for(const auto& p:ps)assemblyPoint(p);if(d.at("is_assembly")==true)require(ps.empty(),"assembly cannot claim leaf features");}
    AssemblyMatrix identity{};for(int i=0;i<4;++i)identity[i][i]=1;
    for(const auto& n:nodes){auto id=n.at("id").get<std::string>(),did=n.at("definition_id").get<std::string>();require(!id.empty()&&id.size()<=4096&&defs.count(did)&&!seen.count(id),"duplicate node or missing definition");const auto& def=*defs.at(did);require(n.at("is_assembly")==def.at("is_assembly")&&n.at("native_placement_equal")==true&&n.at("is_reference").is_boolean()&&n.at("label_name").is_string(),"assembly node flags invalid");auto label=n.at("label_entry").get<std::string>();require(!label.empty()&&label.size()<=256,"label entry invalid");if(n.at("is_reference")==false)require(label==did,"non-reference definition mismatch");
        AssemblyMatrix parent=identity;int depth=1;if(n.at("parent").is_null()){++roots;require(id=="root"+std::to_string(roots)+"/"+label,"root occurrence path mismatch");}else{auto pid=n.at("parent").get<std::string>();require(seen.count(pid)&&seen.at(pid)->at("is_assembly")==true&&id==pid+"/"+label,"missing, cyclic or invalid parent");parent=assemblyMatrix(seen.at(pid)->at("world_matrix"));depth=depths.at(pid)+1;++children[pid];std::string ancestor=pid;while(!ancestor.empty()){require(seen.at(ancestor)->at("definition_id")!=did,"cyclic definition reference");ancestor=seen.at(ancestor)->at("parent").is_null()?"":seen.at(ancestor)->at("parent").get<std::string>();}}
        require(depth<=32,"assembly depth budget");auto component=assemblyMatrix(n.at("component_matrix")),dm=assemblyMatrix(n.at("definition_matrix")),local=assemblyMatrix(n.at("local_matrix")),world=assemblyMatrix(n.at("world_matrix"));if(n.at("is_reference")==false)assemblyMatrixEqual(component,identity);if(definitionMatrices.count(did))assemblyMatrixEqual(dm,definitionMatrices.at(did));else definitionMatrices[did]=dm;assemblyMatrixEqual(local,assemblyProduct(component,dm));assemblyMatrixEqual(world,assemblyProduct(parent,local));
        depths[id]=depth;seen[id]=&n;if(n.at("is_assembly")==false){require(n.at("root_solid_index").is_number_unsigned()||n.at("root_solid_index").is_number_integer(),"root solid index type");require(n.at("root_solid_index").get<double>()>=0&&n.at("root_solid_index").get<double>()<double(meshes.size()),"root solid index out of range");int index=n.at("root_solid_index").get<int>();require(index>=0&&index<int(meshes.size())&&solidIndices.insert(index).second,"root solid bijection mismatch");leaves[id]=&n;const auto& localPoints=def.at("feature_points_mm");const auto& worldPoints=n.at("feature_world_mm");require(worldPoints.is_array()&&worldPoints.size()==localPoints.size(),"feature correspondence count");for(std::size_t i=0;i<localPoints.size();++i){auto p=assemblyPoint(localPoints[i]),q=assemblyPoint(worldPoints[i]);for(int r=0;r<3;++r){double v=world[r][3];for(int k=0;k<3;++k)v+=world[r][k]*p[k];require(std::abs(v-q[r])<=1e-6,"feature transform mismatch");}}}else require(n.at("root_solid_index").is_null(),"assembly has leaf solid index");
    }
    require(definitionMatrices.size()==defs.size(),"unused assembly definition");require(roots>=1&&roots<=32&&tree.at("free_root_count")==roots&&tree.at("flattened_solid_count")==leaves.size()&&leaves.size()==meshes.size(),"assembly root/leaf count mismatch");for(const auto& [id,n]:seen)if(n->at("is_assembly")==true)require(children[id]>0,"empty assembly");
    const auto& bindings=a.at("bindings");const auto& issues=a.at("issues");require(bindings.is_array()&&bindings.size()<=meshes.size()&&issues.is_array()&&issues.size()<=meshes.size(),"binding budget");std::set<std::string> boundNodes,boundParts;
    for(const auto& b:bindings){auto oid=b.at("occurrence_id").get<std::string>(),partid=b.at("part_id").get<std::string>();require(leaves.count(oid)&&boundNodes.insert(oid).second&&boundParts.insert(partid).second,"duplicate/missing occurrence binding");std::size_t pi=0;while(pi<parts.size()&&parts[pi].at("part_id")!=partid)++pi;require(pi<parts.size(),"binding part missing");equal(b.at("mesh"),parts[pi].at("mesh"),"binding mesh identity mismatch");equal(b.at("key"),parts[pi].at("key"),"binding inventory key mismatch");const auto& n=*leaves.at(oid);equal(b.at("definition_id"),n.at("definition_id"),"binding definition mismatch");const auto& points=meshes[pi].mesh.points;auto bounds=n.at("world_bounds_xyzxyz_mm").get<std::array<double,6>>(),occ=parts[pi].at("occ_bounds_xyzxyz_mm").get<std::array<double,6>>();for(int k=0;k<3;++k){require(std::isfinite(bounds[k])&&std::isfinite(bounds[k+3])&&bounds[k]<=bounds[k+3]&&bounds[k]>=occ[k]-1e-5&&bounds[k+3]<=occ[k+3]+1e-5,"CAD broad phase bounds mismatch");for(auto p:points)require(p[k]>=bounds[k]-1e-5&&p[k]<=bounds[k+3]+1e-5,"mesh point outside CAD bounds");}
        const auto& features=n.at("feature_world_mm");const auto& matches=b.at("feature_matches");require(!features.empty()&&matches.is_array()&&matches.size()==features.size(),"feature witnesses missing");for(std::size_t i=0;i<features.size();++i){const auto& m=matches[i];require(m.at("mesh_point_index").is_number_integer(),"feature index type");auto index=m.at("mesh_point_index").get<std::size_t>();require(index<points.size(),"feature index budget");auto p=assemblyPoint(features[i]);double d=0;for(int k=0;k<3;++k)d+=(p[k]-points[index][k])*(p[k]-points[index][k]);d=std::sqrt(d);double reported=m.at("distance_mm").get<double>();require(std::isfinite(reported)&&reported>=0&&d<=1e-5&&std::abs(d-reported)<=1e-9,"feature mesh distance mismatch");}
        auto indices=assemblySamples(points.size());const auto& samples=b.at("boundary_samples");require(samples.is_array()&&samples.size()==indices.size(),"boundary sample count");for(std::size_t i=0;i<indices.size();++i){require(samples[i].at("mesh_point_index").is_number_integer()&&samples[i].at("mesh_point_index")==indices[i],"boundary sample selection mismatch");double d=samples[i].at("distance_to_boundary_mm").get<double>();require(std::isfinite(d)&&d>=0&&d<=1e-5,"recorded boundary sample failed");}
    }
    std::set<std::string> issueParts;for(const auto& issue:issues){auto id=issue.at("part_id").get<std::string>();require(!boundParts.count(id)&&issueParts.insert(id).second&&issue.at("code")=="non_unique_or_missing_correspondence","invalid correspondence issue");bool found=false;for(const auto& p:parts)found=found||p.at("part_id")==id;require(found,"issue part missing");}require(boundParts.size()+issueParts.size()==parts.size(),"missing binding diagnostic");bool qualified=issues.empty()&&bindings.size()==meshes.size()&&boundNodes.size()==leaves.size();require(a.at("qualified")==qualified,"forged assembly qualification");return a;
}

